<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require __DIR__.'/includes/project_manager.php';require_permission('project_finance.manage');$pdo=db();$projectId=(int)($_GET['project_id']??$_POST['project_id']??0);$projects=pm_project_options($pdo);if(!$projectId&&$projects)$projectId=(int)$projects[0]['id'];$pageTitle='Registrar gasto';$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$projectId=(int)($_POST['project_id']??0);$desc=trim((string)($_POST['description']??''));$amount=(float)($_POST['amount']??0);if(!$projectId)$errors[]='Selecciona un proyecto.';if($desc==='')$errors[]='La descripción es obligatoria.';if($amount<=0)$errors[]='El importe debe ser mayor a cero.';if(!$errors){$currency=(string)($_POST['currency']??'USD');if(!in_array($currency,['CLP','USD','BRL'],true))$currency='USD';$pdo->prepare('INSERT INTO project_expenses(project_id,expense_date,category,description,amount,currency,billable,created_by) VALUES (?,?,?,?,?,?,?,?)')->execute([$projectId,($_POST['expense_date']??date('Y-m-d'))?:date('Y-m-d'),trim((string)($_POST['category']??''))?:null,$desc,$amount,$currency,isset($_POST['billable'])?1:0,(int)$_SESSION['user_id']]);flash('success','Gasto registrado.');redirect('project_expenses.php?project_id='.$projectId);}}require __DIR__.'/includes/header.php';?><?php foreach($errors as$e):?><div class="alert alert-error"><?=e($e)?></div><?php endforeach;?><form method="post" class="panel"><div class="panel-header"><h2>Registrar gasto</h2><a class="btn btn-light btn-small" href="project_expenses.php?project_id=<?=$projectId?>">Volver</a></div><div class="panel-body form-grid"><?=csrf_field()?><label>Proyecto<select name="project_id"><?php foreach($projects as$p):?><option value="<?=$p['id']?>" <?=$projectId===(int)$p['id']?'selected':''?>><?=e($p['name'])?></option><?php endforeach;?></select></label><label>Fecha<input type="date" name="expense_date" value="<?=e($_POST['expense_date']??date('Y-m-d'))?>"></label><label>Categoría<input name="category" value="<?=e($_POST['category']??'')?>" placeholder="Software, proveedor, viaje..."></label><label>Descripción<input name="description" required value="<?=e($_POST['description']??'')?>"></label><label>Importe<input type="number" step="0.01" min="0.01" name="amount" required value="<?=e($_POST['amount']??'')?>"></label><label>Moneda<select name="currency"><?php foreach(['CLP','USD','BRL'] as$c):?><option><?=$c?></option><?php endforeach;?></select></label><label class="check-row"><input type="checkbox" name="billable" value="1"> Refacturable al cliente</label><div class="full form-actions"><button class="btn btn-primary">GUARDAR GASTO</button></div></div></form><?php require __DIR__.'/includes/footer.php';?>
